/* emoji_icon_op - an app icon from an emoji, through the HOUSE pipeline (2026-11-17; owner: "for emoji icons user can set, use the in-house pipeline that converts emoji to sprite.csv", "if user changed icon in pdl would it auto update like other things").
 *   emoji_icon_op <house> <icon_dir> set <emoji>    make <icon_dir>/sprite.csv from the emoji, then write emoji.txt (the SETTING) and emoji.made (which emoji the current sprite came from)
 *   emoji_icon_op <house> <icon_dir> sync           if emoji.txt names a different emoji than emoji.made, regenerate sprite.csv; otherwise do nothing (no process is started)
 * The pipeline is the one the tile picker and egg hatching use: emoji_gen_atlas (FreeType + NotoColorEmoji -> PNG) then emoji_xtract (PNG -> the 64 px RGBA csv), both under <house>/_.monads/_.livedesk-taskbar/ops/+x/.
 * Files in <icon_dir>: sprite.csv = PROJECTION (safe to delete, regenerated by sync), emoji.txt = CONFIG (the user edits it, one emoji on the first line), emoji.made = record of what sprite.csv was made from, emoji.failed = an emoji that could not be made
 * (sync does not retry it until emoji.txt changes: a broken emoji must not cost two processes every 5 s). The old sprite.csv is replaced only by a COMPLETE new one (header "# resolution=64", at least 20000 bytes), by rename.
 * Output: ICON-SET | ICON-SYNCED | ICON-UNCHANGED | ICON-KEPT <why>. Exit: 0 ok or unchanged, 1 kept (the old icon stays), 2 usage or a refused emoji. fork/exec only, no shell. Build: gcc -std=gnu11 -Wall -O2 -o +x/emoji_icon_op.+x emoji_icon_op.c */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/wait.h>
#define P 4096
static int run(char *const av[]) { pid_t c = fork(); if (c < 0) return -1; if (c == 0) { int nul = open("/dev/null", O_RDWR); if (nul >= 0) { dup2(nul, 0); dup2(nul, 1); dup2(nul, 2); } execv(av[0], av); _exit(127); }
    int st = 0; for (int i = 0; i < 600; i++) { pid_t r = waitpid(c, &st, WNOHANG); if (r == c) return WIFEXITED(st) ? WEXITSTATUS(st) : -1; usleep(100000); } kill(c, SIGKILL); waitpid(c, &st, 0); return -1; }
static void rd1(const char *f, char *o, size_t cap) { o[0] = 0; FILE *fp = fopen(f, "r"); if (!fp) return; if (fgets(o, (int)cap, fp)) o[strcspn(o, "\r\n")] = 0; fclose(fp); }
static void wr1(const char *f, const char *t) { char tmp[P]; snprintf(tmp, sizeof tmp, "%s.tmp", f); FILE *w = fopen(tmp, "w"); if (!w) return; fprintf(w, "%s\n", t); fclose(w); rename(tmp, f); }
static int emoji_ok(const char *e) { size_t n = strlen(e); if (n == 0 || n > 16) return 0; for (size_t i = 0; i < n; i++) if ((unsigned char)e[i] < 0x20) return 0; return 1; }
/* 0 = a complete icon replaced sprite.csv, 1 = failed (the old icon is untouched) */
static int generate(const char *house, const char *dir, const char *emoji) {
    char ga[P], xt[P], png[P], csv[P], fin[P]; snprintf(ga, sizeof ga, "%s/_.monads/_.livedesk-taskbar/ops/+x/emoji_gen_atlas.+x", house); snprintf(xt, sizeof xt, "%s/_.monads/_.livedesk-taskbar/ops/+x/emoji_xtract.+x", house);
    snprintf(png, sizeof png, "%s/.emoji_tmp.png", dir); snprintf(csv, sizeof csv, "%s/sprite.csv.new", dir); snprintf(fin, sizeof fin, "%s/sprite.csv", dir);
    if (access(ga, X_OK) || access(xt, X_OK)) return 1;
    unlink(csv); char *a1[] = { ga, (char *)emoji, png, NULL }; int r1 = run(a1); char *a2[] = { xt, png, "0", "64", csv, NULL }; int r2 = r1 == 0 ? run(a2) : -1; unlink(png);
    struct stat sb; char h1[40] = ""; rd1(csv, h1, sizeof h1);
    if (r1 != 0 || r2 != 0 || stat(csv, &sb) || sb.st_size < 20000 || strcmp(h1, "# resolution=64")) { unlink(csv); return 1; }
    if (rename(csv, fin) != 0) { unlink(csv); return 1; }
    return 0;
}
int main(int argc, char **argv) {
    if (argc < 4) { fprintf(stderr, "usage: emoji_icon_op <house> <icon_dir> set <emoji> | sync\n"); return 2; }
    const char *house = argv[1], *dir = argv[2], *verb = argv[3]; char f_txt[P], f_made[P], f_fail[P]; snprintf(f_txt, sizeof f_txt, "%s/emoji.txt", dir); snprintf(f_made, sizeof f_made, "%s/emoji.made", dir); snprintf(f_fail, sizeof f_fail, "%s/emoji.failed", dir);
    if (!strcmp(verb, "set") && argc >= 5) {
        if (!emoji_ok(argv[4])) { printf("ICON-KEPT not one emoji\n"); return 2; }
        mkdir(dir, 0755); if (generate(house, dir, argv[4]) != 0) { printf("ICON-KEPT the pipeline could not make that emoji\n"); return 1; }
        wr1(f_txt, argv[4]); wr1(f_made, argv[4]); unlink(f_fail); printf("ICON-SET\n"); return 0; }
    if (!strcmp(verb, "sync")) {
        char want[64], made[64], bad[64]; rd1(f_txt, want, sizeof want); rd1(f_made, made, sizeof made); rd1(f_fail, bad, sizeof bad);
        char sp[P]; snprintf(sp, sizeof sp, "%s/sprite.csv", dir); struct stat sb;
        if (!want[0] || !emoji_ok(want)) { printf("ICON-UNCHANGED\n"); return 0; }
        if (!strcmp(want, made) && stat(sp, &sb) == 0) { printf("ICON-UNCHANGED\n"); return 0; }
        if (!strcmp(want, bad)) { printf("ICON-UNCHANGED\n"); return 0; }
        if (generate(house, dir, want) != 0) { wr1(f_fail, want); printf("ICON-KEPT the pipeline could not make that emoji\n"); return 1; }
        wr1(f_made, want); unlink(f_fail); printf("ICON-SYNCED\n"); return 0; }
    fprintf(stderr, "usage: emoji_icon_op <house> <icon_dir> set <emoji> | sync\n"); return 2;
}
